                            .containsEntry("requestedVersion", "v1");
                });
        // 授权角色不能为空
        assertApiStatus(() -> service.renewLeases("INC-N3", "authorizer-1",
                new LeaseRenewRequest(key(), List.of("T-1", "T-2"), "v2", " ",
