        // 新到期时刻必须晚于续期时刻
        assertApiStatus(() -> renew("INC-N3", "authorizer-1", List.of("T-1", "T-2"), "v2", T0),
                HttpStatus.BAD_REQUEST);
        // 全部失败不改变任何租约
        assertThat(service.taskResourceHistory("INC-N3", "T-1").leases()).hasSize(1);
    }
}

